#include "window.h"
#include <QtWidgets>
#include <QSettings>
#include <QSqlQuery>
void Window::speechOptions(){
 QDialog dialog(this);dialog.setWindowTitle("Synthèse vocale Windows — hors connexion");auto form=new QFormLayout(&dialog);
 auto enabled=new QCheckBox("Lecture vocale générale ON");enabled->setChecked(speechSettings_.enabled);form->addRow(enabled);
 auto voice=new QComboBox;voice->addItem("Voix Windows par défaut","");auto voices=SpeechService::voices();for(auto& v:voices)voice->addItem(v.name+(v.french?" (français)":""),v.id);voice->setCurrentIndex(qMax(0,voice->findData(speechSettings_.voice)));form->addRow("Voix installée",voice);
 auto output=new QComboBox;output->addItem("Périphérique audio par défaut","");for(auto& v:SpeechService::outputs())output->addItem(v.name,v.id);output->setCurrentIndex(qMax(0,output->findData(speechSettings_.output)));form->addRow("Sortie SAPI",output);
 auto volume=new QSpinBox;volume->setRange(0,100);volume->setValue(speechSettings_.volume);auto rate=new QSpinBox;rate->setRange(-10,10);rate->setValue(speechSettings_.rate);auto limit=new QSpinBox;limit->setRange(1,10000);limit->setValue(speechSettings_.limit);auto policy=new QComboBox;policy->addItems({"Refuser le nouveau message","Retirer le plus ancien en attente"});policy->setCurrentIndex(speechSettings_.dropOldest?1:0);form->addRow("Volume",volume);form->addRow("Vitesse (-10 à +10)",rate);form->addRow("Limite de la file",limit);form->addRow("File pleine",policy);
 auto read=[&]{return SpeechSettings{enabled->isChecked(),voice->currentData().toString(),output->currentData().toString(),volume->value(),rate->value(),limit->value(),policy->currentIndex()==1};};
 auto reset=new QPushButton("Rétablir la voix française et la sortie Windows par défaut");reset->setObjectName("resetSpeechDefaults");form->addRow(reset);connect(reset,&QPushButton::clicked,&dialog,[&]{enabled->setChecked(true);voice->setCurrentIndex(0);for(int i=0;i<voices.size();++i)if(voices[i].french){voice->setCurrentIndex(i+1);break;}output->setCurrentIndex(0);volume->setValue(80);rate->setValue(0);});
 auto diagnostic=new QPushButton("Diagnostic local de la voix…");form->addRow(diagnostic);connect(diagnostic,&QPushButton::clicked,&dialog,[&]{QDialog report(&dialog);report.setWindowTitle("Diagnostic voix — aucun texte d’intervention");report.resize(900,600);auto column=new QVBoxLayout(&report);auto text=new QPlainTextEdit;text->setReadOnly(true);QString details="Base utilisée : "+db_.databaseName()+"\nPréférences : "+settingsFile_+"\nGénéral autorisé : "+QString::number(speechSettings_.enabled)+" ; volume : "+QString::number(speechSettings_.volume)+"\n";QSqlQuery query("SELECT ric,active,voice_enabled,pager_enabled FROM capcodes ORDER BY ric",db_);while(query.next())details+=QString("Capcode %1 : actif=%2 ; voix=%3 ; pager=%4\n").arg(query.value(0).toUInt(),7,10,QChar('0')).arg(query.value(1).toInt()).arg(query.value(2).toInt()).arg(query.value(3).toInt());query.finish();QFile file(QFileInfo(db_.databaseName()).absolutePath()+"/technical.log");if(file.open(QIODevice::ReadOnly)){file.seek(qMax<qint64>(0,file.size()-48000));details+="\nJournal technique récent :\n"+QString::fromUtf8(file.readAll());}text->setPlainText(details);column->addWidget(text);auto close=new QDialogButtonBox(QDialogButtonBox::Close);column->addWidget(close);connect(close,&QDialogButtonBox::rejected,&report,&QDialog::reject);report.exec();});
 auto test=new QPushButton("Tester la voix");auto stop=new QPushButton("Arrêter la voix et vider la file");form->addRow(test);form->addRow(stop);connect(test,&QPushButton::clicked,&dialog,[&]{auto settings=read();settings.enabled=true;speech_.configure(settings);speech_.enqueue({QUuid::createUuid().toString(),"POCSAG SDR Pro","Test de lecture vocale Windows. Le récepteur reste indépendant."});});connect(stop,&QPushButton::clicked,&speech_,&SpeechService::stopSpeaking);
 auto buttons=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel);form->addRow(buttons);connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{speechSettings_=read();speech_.configure(speechSettings_);if(voiceAction_)voiceAction_->setChecked(speechSettings_.enabled);storePreferences();dialog.accept();});connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);dialog.exec();speech_.configure(speechSettings_);
}
void Window::replay(QTableView* view){
 auto rows=view->selectionModel()->selectedRows();if(rows.isEmpty())return;auto model=view->model();int row=rows.first().row();auto ric=model->index(row,0).data().toUInt();QString alias;QSqlQuery q(db_);q.prepare("SELECT alias FROM capcodes WHERE CAST(ric AS INTEGER)=?");q.addBindValue(ric);q.exec();if(q.next())alias=q.value(0).toString();if(alias.isEmpty())alias=QString("Capcode %1").arg(ric,7,10,QChar('0'));if(!speechSettings_.enabled){status_->setText("Activer la lecture vocale générale dans Outils");return;}speech_.enqueue({"manual-"+QUuid::createUuid().toString(),alias,model->index(row,model->columnCount()-1).data().toString()});
}
void Window::technical(QString message){
 if(!message.startsWith("Chaîne réception :"))status_->setText(message);QString path=QFileInfo(db_.databaseName()).absolutePath()+"/technical.log";QFile file(path);if(file.size()>2*1024*1024){QFile::remove(path+".1");file.rename(path+".1");file.setFileName(path);}if(file.open(QIODevice::WriteOnly|QIODevice::Append))file.write((QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs)+" "+message+"\r\n").toUtf8());
}
QStringList Window::disabledTypes()const{QStringList list;if(!allowTone_->isChecked())list<<"TONE";if(!allowDiagnostic_->isChecked())list<<"DIAGNOSTIC";return list;}
